from fastmcp import Server
import json

server = Server("summarize-server")

@server.resource_list()
def list_resources():
    return [
        {
            "uri": "template://summarize",
            "name": "summarize",
            "mimeType": "application/vnd.anthropic.message-template"
        }
    ]

@server.resource_read("template://summarize")
def read_summarize_template(uri: str):
    return json.dumps({
        "messages": [
            {
                "role": "user",
                "content": "Please summarize the following text:\n\n{{text}}"
            }
        ]
    })

if __name__ == "__main__":
    server.run()

